import XCTest

@testable import CodeConnect
@testable import CodeConnectKit

/// **A hosted run's model, effort and mode settings, against the daemon's own bytes** (minor 39).
///
/// `minor-39-wire.json` is what ccd emits (`fixtures/claude/`, regenerated by ccd's tests and copied
/// here byte for byte — `check-duplicated-fixtures.sh` keeps the two in step). It carries a live hosted
/// run's `menus` and facts, the three request frames an app sends, and every answer class. The point,
/// as in `Minor35WireTests`: the app's encode is the bytes ccd reads, and its decode is the bytes ccd
/// wrote — proven against the capture, never a hand-built shape.
@MainActor
final class Minor39WireTests: XCTestCase {

    private let uid = "01K1B3XQ8ZC0DE5FGH7JKMNPQR"

    private func wire() throws -> [String: JSONValue] {
        let url = try XCTUnwrap(
            Bundle(for: type(of: self)).url(forResource: "minor-39-wire", withExtension: "json"))
        return try XCTUnwrap(
            try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
    }

    private func frame(_ key: String) throws -> ServerMessage {
        let value = try XCTUnwrap(try wire()[key], "no \(key) in minor-39-wire.json")
        return try JSONDecoder().decode(ServerMessage.self, from: Data(value.canonicalJSONString.utf8))
    }

    private func summary(_ key: String) throws -> SessionSummary {
        let value = try XCTUnwrap(try wire()[key], "no \(key) in minor-39-wire.json")
        return try JSONDecoder().decode(SessionSummary.self, from: Data(value.canonicalJSONString.utf8))
    }

    /// A live hosted run carries the menus an app sets it from, and its current facts, exactly as the
    /// daemon sent them — models with their efforts, modes with the agent's own labels.
    func testALiveHostedRunCarriesItsMenusAndFacts() throws {
        let s = try summary("session_hosted_live")
        let menus = try XCTUnwrap(s.menus, "a live hosted run carries menus")
        XCTAssertEqual(menus.models.map(\.value), ["default", "sonnet"])
        XCTAssertEqual(menus.models.map(\.label), ["Default (recommended)", "Sonnet"])
        XCTAssertEqual(menus.models.first?.efforts, ["low", "medium", "high", "xhigh", "max"])
        XCTAssertEqual(menus.modes.map(\.value), ["default", "acceptEdits", "plan", "bypassPermissions"])
        XCTAssertEqual(menus.modes.map(\.label), ["Ask before edits", "Accept edits", "Plan", "Bypass permissions"])
        XCTAssertEqual(menus.selectedModel, "sonnet", "the daemon states the chosen model (minor 39)")
        XCTAssertEqual(s.effort?.value, "high")
        // After an app's change the fact is the chosen entry's id (minor 45), never claude's receipt.
        XCTAssertEqual(s.model?.value, "claude-sonnet-5-5")
        XCTAssertEqual(s.permissionMode?.value, "plan")
    }

    /// The same daemon's older summary — no `menus`, no `effort` fact — is where an app draws no
    /// controls at all. The one field that gates them, decoded as absent.
    func testAnOlderSummaryCarriesNoMenus() throws {
        let s = try summary("session_hosted_live_minor_38")
        XCTAssertNil(s.menus, "a minor-38 summary carries no menus")
        XCTAssertNil(s.effort, "a minor-38 summary carries no effort fact")
    }

    /// Each answer class decodes as the daemon sent it, correlated to the request that asked. `applied`
    /// carries only when it takes hold; the refusals and the indeterminate carry the agent's sentence.
    func testEachSettingAnswerDecodesAsTheDaemonSentIt() throws {
        let answers: [(String, String, SettingResult)] = [
            ("applied_now", "model-1", .applied(applies: .now)),
            ("applied_mode_during_a_turn", "mode-1", .applied(applies: .now)),
            ("applied_effort", "effort-1", .applied(applies: .nextTurn)),
            ("indeterminate", "mode-3",
                .indeterminate(reason: "Claude didn’t answer, so the change may or may not have been made.")),
            ("refused_bypass", "mode-2",
                .refused(reason: "Turning on Bypass permissions needs your confirmation in the app; nothing was changed.")),
            ("refused_partial", "model-2",
                .refused(reason: "The model was changed; the effort was not: Invalid effort level")),
        ]
        for (key, requestID, expected) in answers {
            guard case .settingResult(let session, let request, let result) = try frame(key) else {
                XCTFail("\(key) is not a setting_result")
                continue
            }
            XCTAssertEqual(session, uid, key)
            XCTAssertEqual(request, requestID, key)
            XCTAssertEqual(result, expected, key)
        }
    }

    /// The three requests an app sends are the bytes ccd reads: a model change, an effort change
    /// (riding `set_model` with no model), and a mode change. `nil` fields are omitted, never null.
    func testTheSettingRequestsAreTheBytesTheDaemonReads() throws {
        func encoded(_ message: ClientMessage) throws -> JSONValue {
            try JSONDecoder().decode(JSONValue.self, from: JSONEncoder().encode(message))
        }
        XCTAssertEqual(
            try encoded(.setModel(session: uid, requestID: "model-1", model: "sonnet", effort: nil)),
            try XCTUnwrap(try wire()["set_model_request"]))
        XCTAssertEqual(
            try encoded(.setModel(session: uid, requestID: "effort-1", model: nil, effort: "high")),
            try XCTUnwrap(try wire()["set_effort_request"]))
        XCTAssertEqual(
            try encoded(.setMode(session: uid, requestID: "mode-1", mode: "plan", confirmed: false)),
            try XCTUnwrap(try wire()["set_mode_request"]))
    }
}
